namespace XForge.DesignSystem.Components.AI.Documents;

/// <summary>
/// Represents a complete report configuration generated by AI from natural language.
/// Contains field selections, filters, grouping, sorting, format, and AI-generated summary.
/// </summary>
public sealed class XFAiReportDefinition
{
    /// <summary>Unique identifier for this report definition.</summary>
    public string Id { get; set; } = Guid.NewGuid().ToString("N")[..8];

    /// <summary>Report title generated by AI.</summary>
    public string Title { get; set; } = string.Empty;

    /// <summary>Human-readable description of the report.</summary>
    public string Description { get; set; } = string.Empty;

    /// <summary>The original natural language query from the user.</summary>
    public string? NaturalLanguageQuery { get; set; }

    /// <summary>Fields selected for inclusion in the report.</summary>
    public IReadOnlyList<XFAiReportField> SelectedFields { get; set; } = Array.Empty<XFAiReportField>();

    /// <summary>Filters to apply to the report data.</summary>
    public IReadOnlyList<XFAiReportFilter> Filters { get; set; } = Array.Empty<XFAiReportFilter>();

    /// <summary>Field name to group results by.</summary>
    public string? GroupByField { get; set; }

    /// <summary>Field name to sort results by.</summary>
    public string? SortByField { get; set; }

    /// <summary>Whether to sort in descending order.</summary>
    public bool SortDescending { get; set; }

    /// <summary>Export format for the report.</summary>
    public XFAiReportFormat Format { get; set; } = XFAiReportFormat.Pdf;

    /// <summary>AI-generated summary of the report purpose and contents.</summary>
    public string? AiSummary { get; set; }

    /// <summary>AI-generated SQL query (when applicable).</summary>
    public string? GeneratedSql { get; set; }

    /// <summary>AI confidence score for the generated report (0.0–1.0).</summary>
    public double Confidence { get; set; }

    /// <summary>Additional metadata from the AI provider.</summary>
    public Dictionary<string, string>? Metadata { get; set; }
}

/// <summary>
/// Represents a data field available for report generation.
/// </summary>
public sealed class XFAiReportField
{
    /// <summary>Internal field name (database column or property name).</summary>
    public string Name { get; set; } = string.Empty;

    /// <summary>Localized display name for the field.</summary>
    public string DisplayName { get; set; } = string.Empty;

    /// <summary>Data type of the field (string, number, date, boolean, etc.).</summary>
    public string DataType { get; set; } = "string";

    /// <summary>Whether this field is required in the report.</summary>
    public bool IsRequired { get; set; }
}

/// <summary>
/// Represents a filter condition applied to a report field.
/// </summary>
public sealed class XFAiReportFilter
{
    /// <summary>Field name to filter on.</summary>
    public string Field { get; set; } = string.Empty;

    /// <summary>Comparison operator (eq, ne, gt, lt, gte, lte, contains, startsWith, etc.).</summary>
    public string Operator { get; set; } = string.Empty;

    /// <summary>Filter value.</summary>
    public string? Value { get; set; }
}

/// <summary>
/// Supported export formats for AI-generated reports.
/// </summary>
public enum XFAiReportFormat
{
    /// <summary>Adobe PDF document.</summary>
    Pdf,

    /// <summary>Microsoft Excel spreadsheet.</summary>
    Excel,

    /// <summary>Comma-separated values.</summary>
    Csv,

    /// <summary>Microsoft Word document.</summary>
    Word,

    /// <summary>Interactive dashboard view.</summary>
    Dashboard
}
